previewCss:
.darma-loader-darma-b11-puzzle-assemble { --accent: var(--loader-color, #8b5cf6); --accent-2: var(--loader-secondary-color, #ec4899); width: var(--loader-size, 80px); height: var(--loader-size, 80px); position: relative; }
.darma-loader-darma-b11-puzzle-assemble span { position: absolute; width: 46%; height: 46%; background: linear-gradient(135deg, var(--accent), var(--accent-2)); border: 1px solid color-mix(in srgb, #fff 25%, transparent); }
.darma-loader-darma-b11-puzzle-assemble span:nth-child(1) { left: 2%; top: 2%; border-radius: 22% 0 0 0; animation: darma-loader-darma-b11-puzzle-assemble-pz-tl calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b11-puzzle-assemble span:nth-child(2) { right: 2%; top: 2%; border-radius: 0 22% 0 0; animation: darma-loader-darma-b11-puzzle-assemble-pz-tr calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b11-puzzle-assemble span:nth-child(3) { left: 2%; bottom: 2%; border-radius: 0 0 0 22%; animation: darma-loader-darma-b11-puzzle-assemble-pz-bl calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b11-puzzle-assemble span:nth-child(4) { right: 2%; bottom: 2%; border-radius: 0 0 22% 0; animation: darma-loader-darma-b11-puzzle-assemble-pz-br calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
@keyframes darma-loader-darma-b11-puzzle-assemble-pz-tl { 0%, 100% { transform: translate(-70%, -70%); opacity: 0; } 40%, 82% { transform: translate(0, 0); opacity: 1; } }
@keyframes darma-loader-darma-b11-puzzle-assemble-pz-tr { 0%, 100% { transform: translate(70%, -70%); opacity: 0; } 40%, 82% { transform: translate(0, 0); opacity: 1; } }
@keyframes darma-loader-darma-b11-puzzle-assemble-pz-bl { 0%, 100% { transform: translate(-70%, 70%); opacity: 0; } 40%, 82% { transform: translate(0, 0); opacity: 1; } }
@keyframes darma-loader-darma-b11-puzzle-assemble-pz-br { 0%, 100% { transform: translate(70%, 70%); opacity: 0; } 40%, 82% { transform: translate(0, 0); opacity: 1; } }

